register_expansion_help <- function(){h<-get("parameter_help",envir=parent.frame())
  extra<-c(fp_model="指数、Weibull、广义Gamma、log风险自然样条、RP log累计风险或正系数I-spline累计风险。三个样条模型含义不同。",fp_candidates="预定候选可含六种模型；共用冻结切点，失败记录原因。AIC/stacking混合预测，非后验BMA。",fp_knots="0–6个正递增风险年龄切点，例3,6,12月。RP使用log年龄坐标；I-spline使用原年龄；log风险样条用log1p年龄。",fp_tail="大于全部内部切点，默认24月。log风险样条在此后风险恒定；RP为上边界，之后log累计风险对log年龄线性；I-spline之后只保留正线性基准风险。",fp_time_scale="参考时间尺度s>0，默认1月。RP使用log(t/s)，log风险样条使用log1p(t/s)；I-spline不使用此参数。单位切换同步转换。",fp_rp_lower="RP正下边界，须小于所有内部切点及上边界，默认0.1月。边界外采用线性log累计风险；不是左截断或最小事件年龄。",fp_rp_intercept="RP eta=log累计风险在log(t/s)坐标的截距，无量纲。默认log(log2/12)，与线性系数1/非线性0/尺度1月合成指数中位12月。",fp_rp_linear="RP log年龄线性项系数，默认1。与非线性项共同决定导数，必须整个年龄轴导数>0；单独为正不足以保证有效模型。",fp_rp_coefficients="RP自然限制三次基函数系数，个数=内部切点数；3切点填0,0,0。无切点时留空。需要全域累计风险单调，代码拒绝不满足条件的参数。",fp_ispline_tail_rate="累计风险中的正线性系数lambda，单位1/当前时间。默认0.02每月；也在边界之前贡献风险，不是只在尾部才启用。",fp_ispline_weights="I-spline基函数的正无量纲权重，个数=内部切点数+4。3切点填7个0.1；无切点仍须4个。不输入对数，不随时间单位变化。")
  h[names(extra)]<-extra
  common<-c(cut_rule="固定日历截点或预定累计观察事件目标。事件目标只计对应阶段新队列及Control/在试验臂，未达到上限时该阶段p=1，不做正式检验。",event_d1="正整数D1，默认120。一次Final计分析终点；两阶段计筛选终点，2-in-1为PFS。阶段结束实际时间可早于日历上限。",event_d2="正整数D2，默认120，只计Stage2新患者的确认终点事件；不将Stage1后续事件并入。",stage1="固定模式的Final/Stage1日期，或事件模式的Stage1最晚日历时间，从研究起点计时，默认18月。",max="两阶段Final共同日历上限，默认42月，须晚于计划Stage1上限。Stage2在实际Stage1截点启动。",test="log-rank或联合PH Cox Wald为正态近似。联合Cox同时拟合全部在场试验臂与Control，以模型协方差作Dunnett相关矩阵。精确landmark仅固定日期、无退出及完整共同年龄随访。",multiplicity="原始全部臂家族的Bonferroni/Holm；或联合Cox单次Final的单步Dunnett型/闭合Dunnett型。闭合交集保留原家族，独立Stage2只分析交集中选中臂。全部Dunnett分支为渐近方法。",dunnett_steps="Miwa确定性多元正态积分网格点，32–512整数，默认128。更高点数增加耗时；奇异相关矩阵报错，不自动修复。",interval_enabled="仅联合Cox可选：原家族同时Bonferroni近似HR区间，独立组合时反演固定权重组合Wald。未选择/无信息臂返回(0,Inf)。不是闭合检验相容区间或无偏估计。",interval_alpha="原家族同时近似HR区间alpha，默认0.05，输出水平0.95；与单侧检验alpha分别设置。",confirmation="仅Stage2或固定w1/w2逆正态组合。闭合方法组合交集局部p，Bonferroni/Holm组合逐臂p；Stage2必须独立新患者。")
  for(pre in c("ma_","ds_"))for(k in names(common))h[paste0(pre,k)]<-common[[k]]
  h["ds_candidates"]<-"固定模式七列label,n1,n2,stage1,max,landmark,w1；事件模式另必需event_d1,event_d2。时间用页面单位，事件数正整数；一次Final忽略D2。最多20预定候选，独立确认，不能在运行中扩展候选。"
  assign("parameter_help",h,envir=parent.frame())
}
